// ─────────────────────────── runtime tests ───────────────────────────────

test('gives back the number it was given', () => {
  eq(identity(5), 5);
});

test('gives back the same object, not a copy', () => {
  const config = { retries: 3 };
  ok(identity(config) === config);
});

test('same() is true for two equal primitives', () => {
  eq(same('a', 'a'), true);
});

test('same() compares by reference, so twins are not the same', () => {
  eq(same({ id: 1 }, { id: 1 }), false);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _r1 = Expect<Equal<ReturnType<typeof identity<string>>, string>>;
type _r2 = Expect<Equal<ReturnType<typeof identity<number[]>>, number[]>>;

function _typeTests() {
  const n: number = identity(5);
  const s: string = identity('hi');
  use(n, s);

  // nobody writes <> at the call site — the argument decides T
  const kept = identity('ready');
  type _k = Expect<Equal<typeof kept, 'ready'>>;
  use(kept);

  // @ts-expect-error — T was pinned to number by hand; a string cannot fit
  identity<number>('nope');

  // @ts-expect-error — both arguments feed the SAME type parameter
  same(1, 'one');

  // @ts-expect-error — same() answers a question, it does not return a value
  const wrong: number = same(1, 2);
  use(wrong);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('builds a two-slot tuple', () => {
  eq(pair(1, 'a'), [1, 'a']);
});

test('the two slots are independent', () => {
  eq(pair('user', { id: 7 }), ['user', { id: 7 }]);
});

test('swapPair reverses the slots', () => {
  eq(swapPair([1, 'a']), ['a', 1]);
});

test('swapping twice gets you back where you started', () => {
  eq(swapPair(swapPair([1, 'a'])), [1, 'a']);
});

test('firstOfPair reads slot zero', () => {
  eq(firstOfPair(['left', 'right']), 'left');
});

// ──────────────────────────── type tests ─────────────────────────────────

type _r1 = Expect<Equal<ReturnType<typeof pair<number, string>>, [number, string]>>;
type _r2 = Expect<Equal<ReturnType<typeof swapPair<number, string>>, [string, number]>>;
type _r3 = Expect<Equal<ReturnType<typeof firstOfPair<boolean, string>>, boolean>>;

function _typeTests() {
  const p = pair(1, 'a');
  type _p = Expect<Equal<typeof p, [number, string]>>;

  const flipped = swapPair(p);
  type _f = Expect<Equal<typeof flipped, [string, number]>>;

  const head = firstOfPair(p);
  type _h = Expect<Equal<typeof head, number>>;
  use(p, flipped, head);

  // @ts-expect-error — order matters: pair('a', 1) is [string, number]
  const backwards: [number, string] = pair('a', 1);
  use(backwards);

  // @ts-expect-error — a tuple is not a free-for-all array; slot 2 does not exist
  firstOfPair([1, 'a', true]);
}
use(_typeTests);

