test('picks the longer string', () => {
  eq(longest('hello', 'hi'), 'hello');
});

test('picks the longer array', () => {
  eq(longest([1, 2], [3, 4, 5]), [3, 4, 5]);
});

test('ties go to the first argument', () => {
  eq(longest('ab', 'cd'), 'ab');
});

test('totalLength adds up every length', () => {
  eq(totalLength(['ab', 'cde']), 5);
});

test('totalLength works on anything with a length', () => {
  eq(totalLength([[1, 2], [3], []]), 3);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _r1 = Expect<Equal<ReturnType<typeof longest<string[]>>, string[]>>;

function _typeTests() {
  const arr = longest([1, 2], [3]);
  type _a = Expect<Equal<typeof arr, number[]>>;
  use(arr);

  // the constraint is not primitive-shaped, but T sits bare in the return
  // type, so the string literals survive as a union
  const s = longest('abc', 'de');
  type _s = Expect<Equal<typeof s, 'abc' | 'de'>>;
  use(s);

  // @ts-expect-error — a number has no .length, so it fails the constraint
  longest(1, 2);

  // @ts-expect-error — one T, so both arguments must be the same type
  longest('abc', [1, 2]);

  // @ts-expect-error — inside an UNCONSTRAINED generic, T has no members
  const noMembers = <U>(x: U): number => x.length;
  use(noMembers);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

const byTime = (a: Date, b: Date): number => a.getTime() - b.getTime();

test('leaves a value that is already in range', () => {
  eq(clamp(5, 1, 10), 5);
});

test('pulls a value up to the low bound', () => {
  eq(clamp(-3, 1, 10), 1);
});

test('pulls a value down to the high bound', () => {
  eq(clamp(15, 1, 10), 10);
});

test('clamps strings alphabetically', () => {
  eq(clamp('m', 'c', 'g'), 'g');
});

test('clampBy orders anything you can compare', () => {
  const low = new Date('2020-01-01');
  const high = new Date('2022-01-01');
  eq(clampBy(new Date('2024-01-01'), low, high, byTime), high);
});

test('clampBy leaves an in-range value alone', () => {
  const value = new Date('2021-01-01');
  eq(clampBy(value, new Date('2020-01-01'), new Date('2022-01-01'), byTime), value);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _r1 = Expect<Equal<ReturnType<typeof clamp<number>>, number>>;
type _r2 = Expect<Equal<ReturnType<typeof clampBy<Date>>, Date>>;

function _typeTests() {
  const value: number = 5;
  const result = clamp(value, 1, 10);
  type _n = Expect<Equal<typeof result, number>>;
  use(result);

  // @ts-expect-error — Date is not a number or a string, so it fails the
  // constraint; that is what clampBy is for
  clamp(new Date(), new Date(), new Date());

  // @ts-expect-error — one T: you cannot mix a number with a string bound
  clamp(5, 1, 'ten');

  // the comparator's parameters are inferred, no annotations needed
  const bounded = clampBy(new Date(), new Date(), new Date(), (a, b) =>
    a.getTime() - b.getTime()
  );
  type _d = Expect<Equal<typeof bounded, Date>>;
  use(bounded);

  // @ts-expect-error — a comparator returns a number, not a boolean
  clampBy(5, 1, 10, (a, b) => a < b);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('reads a number property', () => {
  eq(getProp(user, 'id'), 1);
});

test('reads a string property', () => {
  eq(getProp(user, 'name'), 'Ada');
});

test('reads a nested object by reference', () => {
  const row = { meta: { hits: 2 } };
  eq(getProp(row, 'meta'), { hits: 2 });
});

test('keysOf lists every own key', () => {
  eq(keysOf(user), ['id', 'name', 'admin']);
});

test('keysOf on an empty object is empty', () => {
  eq(keysOf({}), []);
});

// ──────────────────────────── type tests ─────────────────────────────────

type User = typeof user;
type _r1 = Expect<Equal<ReturnType<typeof getProp<User, 'name'>>, string>>;
type _r2 = Expect<Equal<ReturnType<typeof keysOf<User>>, ('id' | 'name' | 'admin')[]>>;

function _typeTests() {
  const id = getProp(user, 'id');
  type _i = Expect<Equal<typeof id, number>>;

  const admin = getProp(user, 'admin');
  type _a = Expect<Equal<typeof admin, boolean>>;
  use(id, admin);

  // @ts-expect-error — 'email' is not a key of user
  getProp(user, 'email');

  // @ts-expect-error — name is a string, and a string is not a number
  const wrong: number = getProp(user, 'name');
  use(wrong);

  const keys = keysOf(user);
  type _k = Expect<Equal<typeof keys, ('id' | 'name' | 'admin')[]>>;
  use(keys);

  // @ts-expect-error — keysOf wants an object, not a primitive
  keysOf(42);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('plucks a string column', () => {
  eq(pluck(users, 'name'), ['Ada', 'Linus']);
});

test('plucks a number column', () => {
  eq(pluck(users, 'id'), [1, 2]);
});

test('plucking an empty list gives an empty list', () => {
  const empty: { id: number }[] = [];
  eq(pluck(empty, 'id'), []);
});

test('setProp replaces one key', () => {
  eq(setProp(users[0]!, 'name', 'Bob').name, 'Bob');
});

test('setProp leaves the original untouched', () => {
  const before = { id: 1, name: 'Ada', admin: true };
  setProp(before, 'name', 'Bob');
  eq(before.name, 'Ada');
});

test('setProp returns a different object, not the same one', () => {
  const before = { id: 1, name: 'Ada', admin: true };
  ok(setProp(before, 'admin', false) !== before);
});

// ──────────────────────────── type tests ─────────────────────────────────

type User = { id: number; name: string; admin: boolean };
type _r1 = Expect<Equal<ReturnType<typeof pluck<User, 'name'>>, string[]>>;
type _r2 = Expect<Equal<ReturnType<typeof setProp<User, 'admin'>>, User>>;

function _typeTests() {
  const names = pluck(users, 'name');
  type _n = Expect<Equal<typeof names, string[]>>;
  use(names);

  const updated = setProp(users[0]!, 'name', 'Bob');
  type _u = Expect<Equal<typeof updated, { id: number; name: string; admin: boolean }>>;
  use(updated);

  // @ts-expect-error — 'email' is not a key of these rows
  pluck(users, 'email');

  // @ts-expect-error — id holds a number, so a string value is rejected
  setProp(users[0]!, 'id', 'seven');

  // @ts-expect-error — the key must exist before you can set it
  setProp(users[0]!, 'nickname', 'Ada');
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('box wraps a value', () => {
  eq(box(2), { value: 2 });
});

test('mapBox transforms the contents and re-boxes them', () => {
  eq(mapBox(box(2), (n: number) => `#${n}`), { value: '#2' });
});

test('ok builds the success branch', () => {
  eq(ok(42), { ok: true, value: 42 });
});

test('err builds the failure branch', () => {
  eq(err('boom'), { ok: false, error: 'boom' });
});

test('isOk tells the branches apart', () => {
  eq(isOk(ok(1)), true);
  eq(isOk(err('boom')), false);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _r1 = Expect<Equal<Box<number>, { value: number }>>;
type _r2 = Expect<Equal<Result<number>, Result<number, Error>>>;
type _r3 = Expect<
  Equal<
    Result<number, string>,
    { ok: true; value: number } | { ok: false; error: string }
  >
>;

function _typeTests() {
  const stringBox = mapBox(box(2), (n: number) => `#${n}`);
  type _b = Expect<Equal<typeof stringBox, Box<string>>>;
  use(stringBox);

  // never fits anywhere, so ok() and err() slot into any Result
  const r: Result<number, string> = ok(1);
  const e: Result<number, string> = err('boom');
  use(r, e);

  if (isOk(r)) {
    const value: number = r.value;
    use(value);
  } else {
    const reason: string = r.error;
    use(reason);
  }

  // @ts-expect-error — .value exists only on the ok branch, so not before the guard
  r.value;

  // @ts-expect-error — a Box<number> does not hold a string
  const wrong: Box<string> = box(2);
  use(wrong);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('pops in last-in-first-out order', () => {
  const s = new TypedStack<number>();
  s.push(1);
  s.push(2);
  eq(s.pop(), 2);
  eq(s.pop(), 1);
});

test('popping an empty stack gives undefined', () => {
  eq(new TypedStack<string>().pop(), undefined);
});

test('peek looks without removing', () => {
  const s = new TypedStack<string>();
  s.push('a');
  eq(s.peek(), 'a');
  eq(s.size, 1);
});

test('two instances keep separate storage', () => {
  const a = new TypedStack<number>();
  const b = new TypedStack<number>();
  a.push(1);
  eq(b.size, 0);
});

test('the registry stores and returns values by key', () => {
  const r = new Registry<{ hp: number }>();
  r.set('goblin', { hp: 7 });
  eq(r.get('goblin'), { hp: 7 });
  eq(r.get('dragon'), undefined);
});

test('the registry reports keys and membership', () => {
  const r = new Registry<number>();
  r.set('a', 1);
  r.set('b', 2);
  eq(r.has('a'), true);
  eq(r.has('zz'), false);
  eq(r.keys(), ['a', 'b']);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _r1 = Expect<Equal<ReturnType<TypedStack<number>['pop']>, number | undefined>>;
type _r2 = Expect<Equal<ReturnType<Registry<string>['get']>, string | undefined>>;

function _typeTests() {
  const stack = new TypedStack<number>();
  stack.push(1);
  const top = stack.pop();
  type _t = Expect<Equal<typeof top, number | undefined>>;
  use(top);

  // @ts-expect-error — this stack was fixed to number at `new`
  stack.push('one');

  // @ts-expect-error — pop() may be empty, so it is not just a number
  const n: number = stack.pop();
  use(n);

  // no argument, no annotation, nothing to infer from
  const bare = new TypedStack();
  type _b = Expect<Equal<typeof bare, TypedStack<unknown>>>;
  use(bare);

  const registry = new Registry<{ hp: number }>();
  const found = registry.get('goblin');
  type _f = Expect<Equal<typeof found, { hp: number } | undefined>>;
  use(found);

  // @ts-expect-error — the value must match the registry's T
  registry.set('goblin', 7);
}
use(_typeTests);

