test('entry keeps the message and the meta it was given', () => {
  eq(entry('saved', { userId: 7 }), { message: 'saved', meta: { userId: 7 } });
});

test('entry works with any meta shape', () => {
  eq(entry('ping', { at: 'noon', retries: 2 }), {
    message: 'ping',
    meta: { at: 'noon', retries: 2 },
  });
});

test('blankEntry supplies an empty meta bag', () => {
  eq(blankEntry('boot'), { message: 'boot', meta: {} });
});

test('emptyBag starts empty', () => {
  eq(emptyBag(), {});
});

// ──────────────────────────── type tests ─────────────────────────────────

type _r1 = Expect<Equal<LogEntry, LogEntry<Record<string, unknown>>>>;
type _r2 = Expect<Equal<LogEntry<{ id: number }>['meta'], { id: number }>>;
type _r3 = Expect<Equal<ReturnType<typeof emptyBag<number>>, Record<string, number>>>;

function _typeTests() {
  // inference beats the default: Meta comes from the argument
  const inferred = entry('saved', { userId: 7 });
  type _i = Expect<Equal<typeof inferred, LogEntry<{ userId: number }>>>;
  use(inferred);

  const blank = blankEntry('boot');
  type _b = Expect<Equal<typeof blank, LogEntry<Record<string, unknown>>>>;
  use(blank);

  // nothing to infer from, so the default is what you get
  const bag = emptyBag();
  type _g = Expect<Equal<typeof bag, Record<string, string>>>;
  use(bag);

  const numbers = emptyBag<number>();
  type _n = Expect<Equal<typeof numbers, Record<string, number>>>;
  use(numbers);

  // @ts-expect-error — the default meta is a loose bag; it is not { id: number }
  const wrong: LogEntry<{ id: number }> = blankEntry('boot');
  use(wrong);
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('zips two arrays of the same length', () => {
  eq(zip([1, 2], ['a', 'b']), [[1, 'a'], [2, 'b']]);
});

test('zip stops at the shorter array', () => {
  eq(zip([1, 2, 3], ['a']), [[1, 'a']]);
});

test('zipping with an empty array gives nothing', () => {
  const empty: string[] = [];
  eq(zip([1, 2], empty), []);
});

test('mapObject keeps the keys and replaces the values', () => {
  eq(mapObject({ a: 'x', b: 'yy' }, (s: string) => s.length), { a: 1, b: 2 });
});

test('mapObject hands the key to the callback too', () => {
  const seen: string[] = [];
  mapObject({ a: 1, b: 2 }, (value: number, key: string) => {
    seen.push(key);
    return value;
  });
  eq(seen, ['a', 'b']);
});

test('mapObject on an empty object gives an empty object', () => {
  eq(mapObject({}, (v: unknown) => v), {});
});

// ──────────────────────────── type tests ─────────────────────────────────

type _r1 = Expect<Equal<ReturnType<typeof zip<number, string>>, [number, string][]>>;
type _r2 = Expect<
  Equal<ReturnType<typeof mapObject<{ a: string; b: string }, number>>, { a: number; b: number }>
>;

function _typeTests() {
  const pairs = zip([1, 2], ['a', 'b']);
  type _z = Expect<Equal<typeof pairs, [number, string][]>>;
  use(pairs);

  const lengths = mapObject({ a: 'x', b: 'yy' }, (s) => s.length);
  type _m = Expect<Equal<typeof lengths, { a: number; b: number }>>;
  use(lengths);

  // @ts-expect-error — the result has exactly the input's keys, and c is not one
  lengths.c;

  const flags = mapObject({ a: 1, b: 2 }, (n) => n > 1);
  type _f = Expect<Equal<typeof flags, { a: boolean; b: boolean }>>;
  use(flags);

  // @ts-expect-error — the callback receives the value type, so .toUpperCase is out
  mapObject({ a: 1 }, (n) => n.toUpperCase());
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('compose2 runs right to left', () => {
  const shout = compose2((s: string) => `${s}!`, (n: number) => `#${n}`);
  eq(shout(2), '#2!');
});

test('compose2 with two number steps', () => {
  const addThenDouble = compose2((n: number) => n * 2, (n: number) => n + 1);
  eq(addThenDouble(3), 8);
});

test('once calls the wrapped function a single time', () => {
  const init = spy((label: string) => `${label}-1`);
  const boot = once(init);
  boot('db');
  boot('db');
  boot('cache');
  eq(init.callCount, 1);
});

test('once replays the first result, even when it is undefined', () => {
  const boot = once(() => undefined);
  eq(boot(), undefined);
  eq(boot(), undefined);
});

test('tap gives back the very same value', () => {
  const items = [3, 1, 2];
  ok(tap(items, (a: number[]) => a.sort()) === items);
});

test('tap runs the side effect', () => {
  const seen: number[] = [];
  tap(7, (n: number) => seen.push(n));
  eq(seen, [7]);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _r1 = Expect<
  Equal<ReturnType<typeof compose2<number, string, boolean>>, (a: number) => boolean>
>;
type _r2 = Expect<Equal<ReturnType<typeof tap<string[]>>, string[]>>;

function _typeTests() {
  const shout = compose2((s: string) => `${s}!`, (n: number) => `#${n}`);
  type _c = Expect<Equal<typeof shout, (a: number) => string>>;
  use(shout);

  // @ts-expect-error — g returns a string, so f must accept a string
  compose2((n: number) => n + 1, (s: string) => s);

  const boot = once((label: string, retries: number) => label.length + retries);
  type _o = Expect<Equal<typeof boot, (label: string, retries: number) => number>>;
  use(boot);

  // @ts-expect-error — the wrapper keeps the exact parameter list
  boot('db', 'twice');

  const sorted = tap([3, 1], (a) => a.sort());
  type _t = Expect<Equal<typeof sorted, number[]>>;
  use(sorted);

  // @ts-expect-error — tap hands the callback the value, and 7 has no .sort
  tap(7, (n) => n.sort());
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('returns the same answer as the wrapped function', () => {
  const fast = memoize((a: number, b: number) => a + b);
  eq(fast(1, 2), 3);
});

test('calls the wrapped function once per distinct argument list', () => {
  const slow = spy((a: number, b: number) => a + b);
  const fast = memoize(slow);
  fast(1, 2);
  fast(1, 2);
  fast(2, 2);
  eq(slow.callCount, 2);
});

test('caches a falsy result instead of recomputing it', () => {
  const slow = spy((n: number) => n * 0);
  const fast = memoize(slow);
  eq(fast(5), 0);
  eq(fast(5), 0);
  eq(slow.callCount, 1);
});

test('works for a function with no arguments', () => {
  const slow = spy(() => 'boot');
  const fast = memoize(slow);
  eq(fast(), 'boot');
  eq(fast(), 'boot');
  eq(slow.callCount, 1);
});

test('memoizeKeyed shares an entry when the keys collide', () => {
  const lookup = spy((name: string) => `<${name}>`);
  const find = memoizeKeyed(lookup, (name: string) => name.toLowerCase());
  eq(find('Ada'), '<Ada>');
  eq(find('ADA'), '<Ada>');
  eq(lookup.callCount, 1);
});

// ──────────────────────────── type tests ─────────────────────────────────

type _r1 = Expect<
  Equal<ReturnType<typeof memoize<[a: number], string>>, (a: number) => string>
>;

function _typeTests() {
  const fast = memoize((a: number, b: number) => a + b);
  type _f = Expect<Equal<typeof fast, (a: number, b: number) => number>>;
  use(fast);

  const value: number = fast(1, 2);
  use(value);

  // @ts-expect-error — the wrapper is not loosely typed; a string is a string
  fast('1', 2);

  // @ts-expect-error — and the arity survives too
  fast(1);

  const find = memoizeKeyed((name: string) => name.length, (name) => name.trim());
  type _k = Expect<Equal<typeof find, (name: string) => number>>;
  use(find);

  // @ts-expect-error — the key function sees the SAME arguments as the wrapped fn
  memoizeKeyed((name: string) => name.length, (id: number) => String(id));
}
use(_typeTests);

// ─────────────────────────── runtime tests ───────────────────────────────

test('keeps only the listed keys', () => {
  eq(pick(user, ['id', 'name']), { id: 1, name: 'Ada' });
});

test('picking nothing gives an empty object', () => {
  eq(pick(user, []), {});
});

test('drops the listed keys', () => {
  eq(omit(user, ['password', 'admin']), { id: 1, name: 'Ada' });
});

test('omit does not mutate the original', () => {
  omit(user, ['password']);
  eq(user.password, 'hunter2');
});

test('pick returns a fresh object', () => {
  ok(pick(user, ['id']) !== user);
});

// ──────────────────────────── type tests ─────────────────────────────────

type User = typeof user;
