//  `Chain<U>`, so the chain CHANGES TYPE as the data flows through it:
//
//      chain([1, 2, 3])            Chain<number>
//        .map(n => `#${n}`)        Chain<string>
//        .filter(s => s !== '#2')  Chain<string>
//        .take(1)                  Chain<string>
//        .toArray()                string[]        → ['#1']
//
