    throw new Error('TODO');
  }

  take(n: number): TODO {
    throw new Error('TODO');
  }

  reduce(fn: TODO, initial: TODO): TODO {
    throw new Error('TODO');
  }

  toArray(): TODO {
    throw new Error('TODO');
  }
}

