test('maps every item', () => {
  eq(chain([1, 2, 3]).map((n: number) => n * 2).toArray(), [2, 4, 6]);
});

test('the callback gets the index too', () => {
  eq(chain(['a', 'b']).map((s: string, i: number) => `${i}${s}`).toArray(), ['0a', '1b']);
});

